fn compute_arith_sum(n: u64) -> u64 {
    let mut sum: u64 = 0;
    let mut idx: u64 = 0;

    // Loop to compute the sum of the first n natural numbers
    while idx < n {
        idx += 1;
        sum += idx;

        // Ensure that the sum remains less than 10,000
        // This check is based on the assumption provided in the problem statement
        assert!(sum < 10_000, "Sum exceeded the limit of 10,000");
    }

    sum
}

